B.acj=new A.n([B.l,"\xc8 pronta una nuova versione.",B.k,"Hay una nueva versi\xf3n disponible.",B.i,"\u65b0\u3057\u3044\u30d0\u30fc\u30b8\u30e7\u30f3\u304c\u3042\u308a\u307e\u3059\u3002",B.h,"\uc0c8 \ubc84\uc804\uc774 \uc900\ube44\ub418\uc5c8\uc2b5\ub2c8\ub2e4.",B.f,"\u65b0\u7248\u672c\u5df2\u51c6\u5907\u5c31\u7eea\u3002",B.j,"Eine neue Version ist verf\xfcgbar."],t.N)
B.adK=new A.n([B.l,"Controlla o sincronizza il salvataggio cloud prima di evocare.",B.k,"Revisa o sincroniza tu partida en la nube antes de invocar.",B.i,"\u53ec\u559a\u524d\u306b\u30af\u30e9\u30a6\u30c9\u30bb\u30fc\u30d6\u3092\u78ba\u8a8d\u307e\u305f\u306f\u540c\u671f\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uc18c\ud658 \uc804\uc5d0 \ud074\ub77c\uc6b0\ub4dc \uc800\uc7a5\uc744 \ud655\uc778\ud558\uac70\ub098 \ub3d9\uae30\ud654\ud558\uc138\uc694.",B.f,"\u53ec\u5524\u524d\u8bf7\u68c0\u67e5\u6216\u540c\u6b65\u4e91\u7aef\u5b58\u6863\u3002",B.j,"Cloud-Spielstand vor der Beschw\xf6rung pr\xfcfen oder synchronisieren."],t.N)
B.adY=new A.n([B.l,"Accedi per completare questa evocazione online salvata.",B.k,"Inicia sesi\xf3n para resolver esta invocaci\xf3n en l\xednea guardada.",B.i,"\u4fdd\u5b58\u3055\u308c\u305f\u30aa\u30f3\u30e9\u30a4\u30f3\u53ec\u559a\u3092\u51e6\u7406\u3059\u308b\u306b\u306f\u30ed\u30b0\u30a4\u30f3\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uc800\uc7a5\ub41c \uc628\ub77c\uc778 \uc18c\ud658\uc744 \ucc98\ub9ac\ud558\ub824\uba74 \ub85c\uadf8\uc778\ud558\uc138\uc694.",B.f,"\u8bf7\u767b\u5f55\u4ee5\u5904\u7406\u5df2\u4fdd\u5b58\u7684\u5728\u7ebf\u53ec\u5524\u3002",B.j,"Anmelden, um diese gespeicherte Online-Beschw\xf6rung abzuschlie\xdfen."],t.N)
B.afK=new A.n([B.l,"Ricompensa PvP in attesa. Nuovo tentativo automatico.",B.k,"Recompensa PvP pendiente. Se reintentar\xe1 autom\xe1ticamente.",B.i,"PvP\u5831\u916c\u3092\u4fdd\u7559\u4e2d\u3067\u3059\u3002\u81ea\u52d5\u7684\u306b\u518d\u8a66\u884c\u3057\u307e\u3059\u3002",B.h,"PvP \ubcf4\uc0c1 \ub300\uae30 \uc911. \uc790\ub3d9\uc73c\ub85c \ub2e4\uc2dc \uc2dc\ub3c4\ud569\ub2c8\ub2e4.",B.f,"PvP\u5956\u52b1\u5f85\u5904\u7406\u3002\u5c06\u81ea\u52a8\u91cd\u8bd5\u3002",B.j,"PvP-Belohnung ausstehend. Automatischer Neuversuch."],t.N)
